query PullRequestByNumber($owner: String!, $repo: String!, $pr_number: Int!) {
	repository(owner: $owner, name: $repo) {
		pullRequest(number: $pr_number) {id,author{login,...on User{id,name}},url,title,body,baseRefName,reviewRequests(first: 100) {nodes {requestedReviewer {__typename,...on User{login,name},...on Bot{login},...on Team{organization{login}name,slug}}}},labels(first:100){nodes{id,name,description,color},totalCount},milestone{number,title,description,dueOn},assignees(first:100){nodes{id,login,name,databaseId},totalCount},number}
	}
}

